import { useEffect, useState } from "react"
import { getOne } from "../../api/ManagerApi"
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';

const initState = {
    userId: 0,
    mID: '',
    mPW: '',
    mName: '',
    mGender: '',
    mbirthDate: '',
    mtel: '',
    mEmail: '',
    mProfileImage: '',
    uAdr: '',

}

function ReadComponent({userId}) {

    const [manager, setManager] = useState(initState);

    useEffect(() => {
        getOne(userId).then(data => {
            console.log(data);
            setManager(data);
        })
    }, [userId]);

    return(
        <TableContainer component={Paper}>
            <Table sx={{ minWidth: 650 }} aria-label="simple table">
                <TableHead>
                    <TableRow>
                        <TableCell>userId</TableCell>
                        <TableCell align="right">ID</TableCell>
                        <TableCell align="right">PW</TableCell>
                        <TableCell align="right">Name</TableCell>
                        <TableCell align="right">Complete</TableCell>
                    </TableRow>
                </TableHead>
                <TableBody>
                    <TableRow>
                        <TableCell component="th" scope="row">
                            {manager.userId}
                        </TableCell>
                        <TableCell align="right">{manager.mID}</TableCell>
                        <TableCell align="right">{manager.mPW}</TableCell>
                        <TableCell align="right">{manager.mName}</TableCell>
                        <TableCell align="right">{manager.complete ? '완료' : '미완료'}</TableCell>
                    </TableRow>
                </TableBody>
            </Table>
        </TableContainer>
    );
}

const makeDiv = (title, value) =>
  <div className="flex justify-center">
    <div className="relative mb-4 flex w-full flex-wrap items-stretch">
      <div className="w-1/5 p-6 text-right font-bold">{title}</div>
        <div className="w-4/5 p-6 rounded-r border border-solid shadow-md">
          {value}
        </div>
      </div>
    </div>

export default ReadComponent;